// メニュー両サイドの立ち絵 (背景なし切り抜き)。PNG は GitHub にバイナリで置けないため data URI で配信する。
(function () {
  var ART = {
    'menu-art-left': 'data:image/webp;base64,',
    'menu-art-right': 'data:image/webp;base64,'
  };
  function apply() {
    Object.keys(ART).forEach(function (id) {
      var el = document.getElementById(id);
      if (!el) return;
      el.onerror = null;
      el.src = ART[id];
      el.style.display = '';
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply);
  else apply();
})();
